package com.valor.configuration;
import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="managed_asset_options") class ManagedAssetOption { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false,length=40) String category; @Column(nullable=false,length=80) String code; @Column(nullable=false,length=160) String label; @Column(length=500) String description; @Column(nullable=false) boolean active=true; @Column(name="display_order",nullable=false) int displayOrder; @Column(name="created_at",nullable=false) LocalDateTime createdAt; @Column(name="updated_at",nullable=false) LocalDateTime updatedAt; @PrePersist void created(){createdAt=updatedAt=LocalDateTime.now();} @PreUpdate void updated(){updatedAt=LocalDateTime.now();} }
interface ManagedAssetOptionRepository extends org.springframework.data.jpa.repository.JpaRepository<ManagedAssetOption,Long> { java.util.List<ManagedAssetOption> findByCategoryAndActiveTrueOrderByDisplayOrderAscIdAsc(String category); org.springframework.data.domain.Page<ManagedAssetOption> findByCategoryOrderByDisplayOrderAscIdAsc(String category,org.springframework.data.domain.Pageable page); boolean existsByCategoryAndCodeIgnoreCase(String category,String code); boolean existsByCategoryAndCodeIgnoreCaseAndIdNot(String category,String code,Long id); }
